"""D010: preserving hierarchy through representation; optimizing weighted paths."""
from html import escape

DECK_ID = 'D010'
TITLE = '树和森林与哈夫曼'


def note(text):
    return '<details class="teacher-note"><summary>教学注记</summary><p>' + text + '</p></details>'


def code(text):
    return '<pre>' + escape(text) + '</pre>'


def table(headers, rows):
    return '<table><thead><tr>' + ''.join('<th>' + x + '</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + x + '</td>' for x in row) + '</tr>' for row in rows) + '</tbody></table>'


def definition(text):
    return '<div class="quote compact-quote"><strong>教材定义（概述）</strong><br>' + text + '</div>'


SLIDES = [
['树和森林与哈夫曼', '<p class="lead">树的表示可以转换，树的形状也可以优化。</p><p>数据结构与算法 · D010</p><p class="small">教材接口：5.6–5.7；回收 5.2–5.3 的编码案例</p>', '课程名'],
['给定的树之外，还能设计什么？', '<p>D009 解决了：在给定结构上安排访问顺序。</p><ol><li>一个结点有多个孩子，怎样只用两个链接保存关系？</li><li>有些叶子使用得更频繁，怎样让总代价更低？</li></ol><p>前一个问题先保留关系，后一个问题允许改变树形。</p>', '回收留问'],
['两份独立的资料目录，怎样作为一个对象？', code('A 项目甲                 G 项目乙\n├── B 模型               └── H 数据\n│   ├── E 网格\n│   └── F 参数\n├── C 结果\n└── D 报告') + definition('森林是 m（m≥0）棵互不相交的树的集合。') + '<p class="small">本例约定：根按 A、G 排列，孩子按图中顺序排列。结点标识互异。</p>', '对象与关系'],
['双亲、孩子、兄弟：保存哪一条关系？', table(['表示','每个结点记录什么','直接支持的操作'], [['双亲表示','一个父结点编号','找父结点'],['孩子表示','直接孩子的列表','依次列出孩子'],['孩子兄弟表示','第一个孩子、下一个兄弟','进入孩子层、沿同层继续']]) + '<p>回收 D008：一个逻辑对象可以有多种表示。<br>兄弟次序先约定，才谈具体转换结果。</p>' + note('对应 5.6.1。若原树无序，先选择孩子顺序；所得二叉形态不必唯一。这里不把排列选择误认为改变父子归属。'), '表示选择'],
['两个链接怎样容纳任意多个孩子？', code('typedef struct CSNode {\n    char id;\n    struct CSNode *first_child;\n    struct CSNode *next_sibling;\n} CSNode;') + '<p>A 的第一个孩子是 B；B 的下一个兄弟是 C，C 的下一个兄弟是 D。</p><p>列出 A 的孩子：从 B 开始，沿兄弟链接依次走到 C、D。</p>', 'C 表示'],
['同一批结点，两种链接含义', '<div class="columns"><div><p>原森林：父子关系</p><pre>A           G\n├─ B        └─ H\n│  ├─ E\n│  └─ F\n├─ C\n└─ D</pre></div><div><p>二叉表示：L / R 标边</p><pre>        A\n       /L   R\\\n      B       G\n    /L R\\    /L\n   E     C   H\n    R\\    R\\\n      F     D</pre></div></div><div class="small">L 编码第一个孩子，R 编码下一个兄弟（含根的次序）。C 的原父结点是谁？</div><details class="teacher-note"><summary>教学注记</summary><p>C 的原父为 A，不是 B；G 是另一个根。请学生沿 B→C→D 的右链还原 A 的孩子。若把 B.right=C 改成 B.left=C，会覆盖 E 并改变原关系，不能当作等价排版。</p></details>', '转换规则'],
['怎样把二叉链接读回森林？', '<ol><li>沿根的右链分出各棵树：A、G。</li><li>对每个结点，左链接给出第一个孩子。</li><li>从该孩子沿右链取出其余孩子，再逐层重复。</li></ol>' + code('A 的孩子：B → C → D\nB 的孩子：E → F        G 的孩子：H') + '<p>验证：结点没丢，原来的父子归属与约定次序都恢复了。</p>' + note('A.right=G 不表示 G 的父结点是 A。恢复时把整条兄弟链赋予同一个原树父结点。孩子链与根链必须无环、不共享结点。'), '反向检查'],
['原树的后根遍历，对应二叉树的什么顺序？', table(['原森林（按根与孩子次序）','二叉表示','本例序列'], [['先序：根，再各孩子子树','先序 NLR','A B E F C D G H'],['后序：各孩子子树，再根','中序 LNR','E F B C D A H G']]) + '<p>左边编码“孩子”，右边编码“后续兄弟”。<br>原树的后根顺序，不能直接照搬成二叉后序。</p>' + note('对应 5.6.3。森林先序为各树先根序串接；这里的森林后序按各树后根序串接，教材也常称森林中序。请学生以原关系定义为准核对。二叉中序先处理孩子链、再根、再后续兄弟，恰好符合这一顺序。'), '回收遍历'],
['先预测：转换后哪些量会变？', '<p><a href="code/forest_demo.c">code/forest_demo.c</a> 编码第 3 页森林，再恢复双亲关系。</p><ul><li>预测 A 的孩子数、森林先序与后序。</li><li>预测右链接为空的结点个数。</li><li>运行后检查：父子关系能否原样恢复？</li></ul>' + note('A 有 3 个孩子。先序 ABEFCDGH，后序 EFBCDAHG。右空为 D、F、G、H，共 4 个。每个非叶结点的孩子链末尾贡献 1 个右空，整个根链末尾再贡献 1 个；非空森林有 q 个非叶结点时，右空数 q+1。本例 q=3，空森林另算。'), '预测与检查'],
['四种消息都用两位编码，够好吗？', '<p>假设一批 16 条状态消息只有四种类型：</p>' + table(['符号','A','B','C','D'], [['出现次数','8','4','2','2'],['等长编码','00','01','10','11']]) + '<p>消息内容占 16×2=32 bit。<br>频繁出现的 A，能不能比其他消息更短？</p><p class="small">教学构造数据；暂只比较编码后的消息内容，不计码表和文件头。</p>', '代价问题'],
['码字变短以后，怎样知道在哪里断开？', code('若 A=0，B=01，C=1\n收到 01：可能是 B，也可能是 A C') + '<p>仅让每个符号的码字不同，还不够。</p>' + definition('前缀编码：任何一个字符的编码都不是另一个字符编码的前缀。') + '<p class="small">它允许从左向右即时确定码字边界。前缀条件是唯一译码的充分条件，并非必要条件。</p>', '编码条件'],
['把符号放在叶子上，能保证什么？', code('左边标 0，右边标 1\n        ●\n      /   \\\n     A     ●\n          / \\\n         B   ●\n            / \\\n           C   D') + '<p>码字是从根到叶子的路径：A=0，B=10，C=110，D=111。<br>叶子不会是另一个叶子的祖先，因此码字互不为前缀。</p>' + note('内部结点不放字符。这里先展示一棵可行编码树，不由“能译码”直接推断最优。译到叶子输出一个符号，再回到根继续。'), '编码树'],
['怎样把“短一些”写成可比较的目标？', definition('树的带权路径长度 WPL，是各叶子权值与根到该叶子路径长度的乘积之和。使给定叶子权值的 WPL 最小的二叉树称为哈夫曼树（最优二叉树）。') + code('WPL = Σ wᵢ ℓᵢ\n本例：8×1 + 4×2 + 2×3 + 2×3 = 28\n平均码长：28 / 16 = 1.75 bit/符号') + '<p class="small">ℓᵢ 数边，根深度为 0；不同于 D008 从 1 开始计的层次。内部权值不直接计入这项求和。</p>', '目标函数'],
['同样四个符号，树形改变了多少代价？', table(['方案','A、B、C、D 的码长','加权总位数'], [['等长编码','2、2、2、2','32'],['第 12 页的树','1、2、3、3','28'],['把 A 与 D 的位置交换','3、2、3、1','40']]) + '<p>树形和符号位置共同影响代价。<br>若权值大却放得深，频繁操作就会反复付出长路径的成本。</p>' + note('交换变化量为 (8−2)×(3−1)=12，28+12=40。树高低不是唯一优化目标；本例较高的树反而比等长树的 WPL 更低。'), '比较与判断'],
['怎样一步步构造低代价的树？', '<ol><li>每个符号作为一棵单结点树，权值取出现次数。</li><li>选择根权值最小的两棵树，合成一个新根，权值为两者之和。</li><li>把新树放回待选集合，重复到只剩一棵。</li></ol><p>每轮少一棵树。n 个符号需要 n−1 次合并。</p>' + note('本讲取正权值、n≥2 的二元前缀编码。并列最小可以任选；为使代码与手算一致，演示按权值、再按结点编号排序，先选者放左边。算法依据不是“试起来不错”，下一段给出交换与收缩理由。'), '哈夫曼算法'],
['合成项放回后，下一轮选谁？', '<p>完整主例 8、4、2、2：合并 4 → 8 → 16，对照第 12 页。</p><pre>补全例：A6、B3、C2、D1\n第 1 轮：D1 + C2 = 新树3\n待选：B3、新树3、A6\n第 2 轮：____ + ____ = ____\n第 3 轮：____ + ____ = ____</pre><p>为什么不能只给最初的叶子排序一次？</p><details class="teacher-note"><summary>教学注记</summary><p>补全为 3+3=6、6+6=12，WPL=3+6+12=21。合成项仍代表待编码的一组符号，必须重新参与最小选择。先收补全，再展开答案；第 24 页另一组权值才作为独立构造证据。</p></details>', '示例与补全'],
['为什么合并权值之和恰好等于 WPL？', code('第 1 次合并：C、D 各多走 1 条边，代价 +4\n第 2 次合并：B、C、D 各多走 1 条边，代价 +8\n第 3 次合并：所有符号各多走 1 条边，代价 +16\n总增量：4 + 8 + 16 = 28') + '<p>每片叶子的权值，被累计的次数恰好等于它的深度。</p>' + note('这一恒等式适用于逐次合并得到的每个内部结点恰有两个孩子的二叉树，不仅仅用于哈夫曼选择。代码用“叶子权值×码长”和“合并权值之和”两条路径交叉核对，但两者相等本身并不证明最优。'), '代价核对'],
['为什么先合并最小两项是安全的？', '<ul><li>可以选取一棵最优树，使两个最小权值处在最深的一对兄弟叶子上。</li><li>把这对兄弟收缩成权值之和，得到更小的同类问题。</li><li>较小问题的最优树展开这对叶子，就给出原问题的最优树。</li></ul><p>安全选择加上规模缩小，让局部选择可以持续进行。</p>' + note('理由展开：正权下可去掉只有一个孩子的内部结点而降低 WPL，因此只需考虑每个内部结点有两个孩子的树。取最深兄弟叶子，把最小两权交换到那里不会增加代价，因为把小权移深、大权移浅的变化量≤0。收缩后若还能改进，展开即改进原树，矛盾。展开多付的固定量为两权之和。这是证明提纲，不以一个例子代替普遍理由。'), '成立理由'],
['合成结点怎样存进 C 数组？', code('typedef struct {\n    unsigned long long weight;\n    int parent, left, right;\n} HNode;\n// 0 .. n-1 为叶子，n .. 2*n-2 为合成结点\n// -1 表示尚无父结点或没有孩子') + '<p>每轮找两个尚无父结点的最小根，再新建父结点。</p><p class="small">n 个叶子、n−1 个内部结点，共 2n−1 个结点；这不保证是 D008 所说的满二叉树。</p>' + note('有两个孩子的内部结点不代表每层都填满。编码从叶子沿 parent 回到根时，先收集的是末位，最后须反转。代码检查整数溢出与固定容量。'), '计算表示'],
['树最优了，实现就一定快吗？', table(['工作','本演示实现','代价（n 个符号）'], [['每轮选两个最小根','扫描尚未被合并的根','单轮 O(n)，构树 O(n²)'],['从叶子生成码字','沿父链接回溯再反转','总计 O(Σℓᵢ)，最坏 O(n²)'],['译码','逐位沿树走，到叶子回根','O(L)，L 为输入位数']]) + '<p>最优 WPL 描述编码目标；构造算法的运行成本是另一件事。</p>' + note('若用最小优先队列，构树可做到 O(n log n)，堆的机制留待 D020。存树 O(n)，若保存所有码字，最坏需要 O(n²) 字符。本课固定容量仅服务小规模演示。'), '算法代价'],
['收到 010110111，怎样还原消息？', table(['读入片段','走到的叶子','动作'], [['0','A','输出 A，回根'],['10','B','输出 B，回根'],['110','C','输出 C，回根'],['111','D','输出 D，回根']]) + '<p>结果为 ABCD。若输入在 <code>11</code> 处结束，停在内部结点，应报告码字不完整。</p>' + note('码表是第 12 页那一份。前缀编码不自动检测所有传输错误：一个比特翻转可能仍译成合法序列。不能把“可以译码”说成“能够纠错”。'), '译码与边界'],
['先预测：两组频率还会得到相同收益吗？', '<p><a href="code/huffman_demo.c">code/huffman_demo.c</a> 对照两组权值：</p>' + table(['输入','合并权值之和','WPL','等长位数'], [['8、4、2、2','？','？','32'],['4、4、4、4','？','？','32']]) + '<p>先预测，再运行：比较码长与总代价，并检查 <code>ABCD</code> 编码后能否还原。</p>' + note('第一组 28、28、32，平均码长 1.75；第二组 32、32、32，平均码长 2。并列权可有不同合法码字，比较 WPL、前缀性和往返结果，不能只比较某一串 0/1。两例码表见程序输出。'), '预测与运行'],
['少了 4 bit，就一定让文件更小吗？', '<p>本例内容从 32 bit 降到 28 bit，节省 12.5%。</p><ul><li>解码端还需要知道码表或树。</li><li>文件可能包含长度、头部和字节对齐填充。</li><li>短消息的额外开销可能超过节省量。</li></ul><p class="small">哈夫曼在给定权值的二元逐符号前缀编码中最优，不表示对所有压缩方法或完整文件都最优。</p>' + note('码表需与当前编码一致。单符号字母表的结构深度是 0，本演示约定码字为 0，于是线上码长为 1，另行处理。零频符号本演示拒绝，可在建模时移出字母表。'), '适用边界'],
['换一组频率，你能独立优化结构吗？', code('四种事件 P、Q、R、S 的次数为：5、2、1、1') + '<ol><li>手工完成每轮最小合并，画出编码树。</li><li>给出码字、WPL 与平均码长。</li><li>与每个符号 2 bit 的方案比较，并说明优化的量。</li></ol>' + note('保留 7 分钟独立作答、2 分钟核对。合并权值 2、4、9，WPL=15，平均 15/9=5/3；等长为 18。一个可行码表 P=1、Q=00、R=010、S=011。并列情况下允许其他最优结果，判定须包含前缀性、每轮选择和代价，不要求码字逐字相同。'), '独立学习证据'],
['两种“改变树”，分别保持什么、改变什么？', table(['操作','必须保持','改变 / 目标'], [['树或森林转孩子兄弟表示','原结点、父子归属、约定次序','链接含义与存储方式'],['按频率构造哈夫曼树','符号、权值、前缀编码条件','树形与码长，使 WPL 最小'],['根据码树译码','码表一致、码字边界有效','位串恢复为符号串']]) + '<p>先明确对象和条件，再决定哪些结构可以改变。</p>', '结构化收口'],
['课后：教材导航与本周作业', '<p><strong>教材导航</strong>：精读 5.6–5.7，回看 5.2–5.3 的编码案例。</p><p><strong>A. 书本习题</strong>：第 5 章选择题 <strong>(1)(9)(11)(14)</strong>、应用题 <strong>(2)③、(3)</strong>。选择题附理由；应用题给出转换、构造与计算过程。</p><p><strong>B. 扩展作业</strong>：对新权值 A7、B3、C2、D1，先提交合并过程、码表、WPL、平均码长与等长比较；运行 <code>code/huffman_demo.c</code> 核对 homework 输出及 ABCD 往返译码。码字不同须解释是否仍最优。</p><p class="small">按<a href="../../assignments/homework-guide.md">作业规范</a>提交 A、B，附 3–5 行过程记录。<br>自学练习（不提交）：选择题 (6)、应用题 (4)；应 (2)③ 可先借助 D009 的恢复方法画出题设二叉树。</p>', '课后衔接'],
['一个对象可以同时连接多个对象，树还够用吗？', '<p>树与森林保留了单一归属的层次关系。<br>编码树则用路径表达符号，按代价优化树形。</p><p class="lead">道路之间可以成环，一个地点也可能连接多个方向，该怎样表示？</p><p>D011：图与一般关系结构。</p>', '留下问题'],
]
